package app.still.planner;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import java.text.*;import org.json.*;
public class ReminderReceiver extends BroadcastReceiver {
 static final int IMMUTABLE=0x04000000;static final String CHANNEL="still_reminders";
 public static void channel(Context c){if(Build.VERSION.SDK_INT>=26)try{Class<?> cl=Class.forName("android.app.NotificationChannel");Object channel=cl.getConstructor(String.class,CharSequence.class,int.class).newInstance(CHANNEL,"Still reminders",3);Object nm=c.getSystemService(Context.NOTIFICATION_SERVICE);nm.getClass().getMethod("createNotificationChannel",cl).invoke(nm,channel);}catch(Exception ignored){}}
 public void onReceive(Context c,Intent intent){channel(c);String title=intent.getStringExtra("title");if(title==null)return;try{Intent open=new Intent(c,MainActivity.class);if("focus".equals(intent.getStringExtra("kind")))open.putExtra("action","focus");PendingIntent pi=PendingIntent.getActivity(c,10,open,PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE);Notification.Builder b=new Notification.Builder(c).setContentTitle(title).setContentText(intent.getStringExtra("body")).setSmallIcon(R.drawable.app_icon).setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER);if(Build.VERSION.SDK_INT>=26)Notification.Builder.class.getMethod("setChannelId",String.class).invoke(b,CHANNEL);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(intent.getIntExtra("notificationId",1),b.build());}catch(Exception ignored){}reschedule(c);TodayWidget.refreshAll(c);}
 static synchronized void reschedule(Context c){Store store=new Store(c);try{String raw=store.load();if(raw.isEmpty())return;JSONObject root=new JSONObject(raw),prefs=root.getJSONObject("preferences");AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);SharedPreferences sp=c.getSharedPreferences("alarms",0);int old=sp.getInt("count",0);for(int i=1;i<=old;i++){PendingIntent p=PendingIntent.getBroadcast(c,i,new Intent(c,ReminderReceiver.class),PendingIntent.FLAG_NO_CREATE|IMMUTABLE);if(p!=null){am.cancel(p);p.cancel();}}int count=0;if(prefs.optBoolean("notifications")){JSONArray ts=root.getJSONArray("tasks");for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);if(t.optBoolean("reminder")&&!t.optBoolean("archived")&&!"done".equals(t.optString("status"))){long at=parse(t.optString("dueDate"),t.optString("dueTime"));if(at>System.currentTimeMillis())schedule(c,++count,at,t.optString("title"),"A little nudge from Still","task");}}JSONArray hs=root.getJSONArray("habits");for(int i=0;i<hs.length();i++){JSONObject h=hs.getJSONObject(i);if(h.optBoolean("paused")||h.optString("reminder").isEmpty())continue;Calendar cal=Calendar.getInstance();for(int n=0;n<367;n++){String day=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(cal.getTime());boolean due=habitDue(h,day);int done=0;JSONArray logs=h.optJSONArray("completions");if(logs!=null)for(int j=0;j<logs.length();j++)if(day.equals(logs.getJSONObject(j).optString("date")))done++;long at=parse(day,h.optString("reminder"));if(due&&done<h.optInt("target",1)&&at>System.currentTimeMillis()){schedule(c,++count,at,h.optString("name"),"Make a little space for your routine","habit");break;}cal.add(Calendar.DAY_OF_MONTH,1);}}}TimerAlerts.refresh(c,root);sp.edit().putInt("count",count).apply();}catch(Exception ignored){}finally{store.close();}}
 static boolean habitDue(JSONObject h,String day){if(h.optBoolean("paused")||day.compareTo(h.optString("startDate"))<0)return false;String f=h.optString("frequency");Calendar cal=Calendar.getInstance();cal.setTimeInMillis(parse(day,"12:00"));if("weekdays".equals(f)){JSONArray ds=h.optJSONArray("days");if(ds!=null)for(int i=0;i<ds.length();i++)if(ds.optInt(i)==cal.get(Calendar.DAY_OF_WEEK)-1)return true;return false;}if("weekly".equals(f)){Calendar start=Calendar.getInstance();start.setTimeInMillis(parse(h.optString("startDate"),"12:00"));return start.get(Calendar.DAY_OF_WEEK)==cal.get(Calendar.DAY_OF_WEEK);}if("custom".equals(f)){try{SimpleDateFormat df=new SimpleDateFormat("yyyy-MM-dd",Locale.US);df.setTimeZone(TimeZone.getTimeZone("UTC"));long diff=(df.parse(day).getTime()-df.parse(h.optString("startDate")).getTime())/86400000L;return diff%Math.max(1,h.optInt("interval",1))==0;}catch(Exception e){return false;}}return true;}
 static long parse(String day,String time){try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setLenient(false);return f.parse(day+" "+time).getTime();}catch(Exception e){return 0;}}
 static void schedule(Context c,int id,long at,String title,String body,String kind){Intent i=new Intent(c,ReminderReceiver.class).putExtra("title",title).putExtra("body",body).putExtra("kind",kind).putExtra("notificationId",id);PendingIntent p=PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);}
}
